# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">THEME 4: FAMILY LIFE — JOBS, WORKPLACES &amp; FAMILY ROUTINES (ENG.9.4)</text>\n  <rect x="20" y="45" width="210" height="105" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="125" y="66" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e40af">PROFESSIONS (MESLEKLER)</text>\n  <text x="125" y="88" text-anchor="middle" font-size="10.5" fill="#1d4ed8">architect (mimar) · engineer</text>\n  <text x="125" y="106" text-anchor="middle" font-size="10.5" fill="#1d4ed8">surgeon (cerrah) · pharmacist</text>\n  <text x="125" y="124" text-anchor="middle" font-size="10.5" fill="#1d4ed8">lawyer (avukat) · accountant</text>\n  <text x="125" y="140" text-anchor="middle" font-size="10.5" fill="#1d4ed8">journalist · chef ·software dev.</text>\n  <rect x="245" y="45" width="210" height="105" rx="10" fill="#f0fdf4" stroke="#16a34a" stroke-width="2"/>\n  <text x="350" y="66" text-anchor="middle" font-size="12" font-weight="bold" fill="#15803d">ASKING ABOUT JOBS</text>\n  <text x="350" y="88" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#14532d">• What does your mother do?</text>\n  <text x="350" y="106" text-anchor="middle" font-size="10" fill="#166534">→ She is an architect.</text>\n  <text x="350" y="124" text-anchor="middle" font-size="10" fill="#166534">→ She designs buildings at an</text>\n  <text x="350" y="140" text-anchor="middle" font-size="10" fill="#166534">office. (Present Simple: V-s)</text>\n  <rect x="470" y="45" width="210" height="105" rx="10" fill="#fffbeb" stroke="#d97706" stroke-width="2"/>\n  <text x="575" y="66" text-anchor="middle" font-size="12" font-weight="bold" fill="#b45309">WORK EXPRESSIONS</text>\n  <text x="575" y="88" text-anchor="middle" font-size="10.5" fill="#78350f">• work in shifts (vardiyalı)</text>\n  <text x="575" y="106" text-anchor="middle" font-size="10.5" fill="#78350f">• work part-time / full-time</text>\n  <text x="575" y="124" text-anchor="middle" font-size="10.5" fill="#78350f">• work from home (freelance)</text>\n  <text x="575" y="140" text-anchor="middle" font-size="10.5" fill="#78350f">• earn a living / retire (emekli)</text>\n  <rect x="20" y="162" width="660" height="82" rx="10" fill="#faf5ff" stroke="#9333ea" stroke-width="2"/>\n  <text x="350" y="185" text-anchor="middle" font-size="12" font-weight="bold" fill="#7e22ce">EXTENDED FAMILY &amp; HOUSEHOLD RESPONSIBILITIES</text>\n  <text x="38" y="208" font-size="11" font-weight="bold" fill="#581c87">• Relatives: nephew (erkek yeğen), niece (kız yeğen), cousin, brother-in-law, mother-in-law, stepfather.</text>\n  <text x="38" y="228" font-size="11" font-weight="bold" fill="#581c87">• Chores: set the table, load the dishwasher, vacuum the floor, take out the rubbish, do the laundry.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">SPECIAL DAYS, CELEBRATIONS &amp; INVITATION COLLOCATIONS</text>\n  <rect x="20" y="45" width="320" height="195" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="180" y="68" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#1e40af">CELEBRATIONS &amp; TRADITIONS</text>\n  <text x="35" y="96" font-size="11" font-weight="bold" fill="#1e3a8a">• Religious &amp; National Festivals (Bayramlar)</text>\n  <text x="35" y="120" font-size="11" font-weight="bold" fill="#1e3a8a">• Wedding anniversary / Graduation ceremony</text>\n  <text x="35" y="144" font-size="11" font-weight="bold" fill="#1e3a8a">• Family reunion / Housewarming party</text>\n  <text x="35" y="168" font-size="11" font-weight="bold" fill="#1e3a8a">• Throw a surprise party / Wrap presents</text>\n  <text x="35" y="192" font-size="11" font-weight="bold" fill="#1e3a8a">• Decorate the house / Blow out the candles</text>\n  <text x="35" y="216" font-size="11" font-weight="bold" fill="#b91c1c">• Visit elderly relatives &amp; kiss their hands</text>\n  <rect x="360" y="45" width="320" height="195" rx="10" fill="#f0fdf4" stroke="#16a34a" stroke-width="2"/>\n  <text x="520" y="68" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#15803d">INVITATIONS: ACCEPTING &amp; REFUSING</text>\n  <text x="378" y="94" font-size="11" font-weight="bold" fill="#14532d">Making an Invitation:</text>\n  <text x="378" y="112" font-size="10.5" fill="#166534">• Would you like to join our family dinner?</text>\n  <text x="378" y="130" font-size="10.5" fill="#166534">• How about / What about having a barbecue?</text>\n  <text x="378" y="156" font-size="11" font-weight="bold" fill="#15803d">Accepting (Kabul Etme):</text>\n  <text x="378" y="174" font-size="10.5" fill="#166534">• I\'d love to! / That sounds great! / Count me in!</text>\n  <text x="378" y="200" font-size="11" font-weight="bold" fill="#dc2626">Refusing Politely (Nazikçe Reddetme):</text>\n  <text x="378" y="218" font-size="10.5" fill="#991b1b">• I\'d love to, but I have to study for my exam.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">TALKING ABOUT FUTURE PLANS: BE GOING TO vs. PRESENT CONTINUOUS vs. WILL</text>\n  <rect x="20" y="45" width="210" height="195" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="125" y="66" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e40af">1. BE GOING TO + V₁</text>\n  <text x="125" y="88" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#1e3a8a">Prior Plans &amp; Intentions</text>\n  <text x="125" y="108" text-anchor="middle" font-size="10" fill="#1d4ed8">Önceden karar verilmiş niyetler</text>\n  <text x="125" y="124" text-anchor="middle" font-size="10" fill="#1d4ed8">ve güçlü kanıta dayalı tahminler.</text>\n  <text x="125" y="152" text-anchor="middle" font-size="10" font-weight="bold" fill="#1e40af">• We are going to visit our</text>\n  <text x="125" y="168" text-anchor="middle" font-size="10" font-weight="bold" fill="#1e40af">grandparents this weekend.</text>\n  <text x="125" y="196" text-anchor="middle" font-size="10" fill="#b91c1c">• Look at those black clouds!</text>\n  <text x="125" y="212" text-anchor="middle" font-size="10" fill="#b91c1c">It is going to rain.</text>\n  <rect x="245" y="45" width="210" height="195" rx="10" fill="#f0fdf4" stroke="#16a34a" stroke-width="2"/>\n  <text x="350" y="66" text-anchor="middle" font-size="12" font-weight="bold" fill="#15803d">2. PRESENT CONTINUOUS</text>\n  <text x="350" y="88" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#14532d">Fixed Arrangements (am/is/are V-ing)</text>\n  <text x="350" y="108" text-anchor="middle" font-size="10" fill="#166534">Yeri, saati ve bileti kesinleşmiş</text>\n  <text x="350" y="124" text-anchor="middle" font-size="10" fill="#166534">yakın gelecek organizasyonları.</text>\n  <text x="350" y="152" text-anchor="middle" font-size="10" font-weight="bold" fill="#15803d">• My sister is getting married</text>\n  <text x="350" y="168" text-anchor="middle" font-size="10" font-weight="bold" fill="#15803d">on Saturday at 7 p.m.</text>\n  <text x="350" y="196" text-anchor="middle" font-size="10" fill="#166534">• I am flying to Izmir</text>\n  <text x="350" y="212" text-anchor="middle" font-size="10" fill="#166534">tomorrow morning at 8:30.</text>\n  <rect x="470" y="45" width="210" height="195" rx="10" fill="#fffbeb" stroke="#d97706" stroke-width="2"/>\n  <text x="575" y="66" text-anchor="middle" font-size="12" font-weight="bold" fill="#b45309">3. WILL + V₁ (SIMPLE FUTURE)</text>\n  <text x="575" y="88" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#78350f">Spontaneous Decisions &amp; Promises</text>\n  <text x="575" y="108" text-anchor="middle" font-size="10" fill="#78350f">Konuşma anında alınan ani</text>\n  <text x="575" y="124" text-anchor="middle" font-size="10" fill="#78350f">kararlar, sözler ve kişisel tahmin.</text>\n  <text x="575" y="152" text-anchor="middle" font-size="10" font-weight="bold" fill="#b45309">• The phone is ringing.</text>\n  <text x="575" y="168" text-anchor="middle" font-size="10" font-weight="bold" fill="#b45309">I will answer it!</text>\n  <text x="575" y="196" text-anchor="middle" font-size="10" fill="#78350f">• I think/hope our family</text>\n  <text x="575" y="212" text-anchor="middle" font-size="10" fill="#78350f">reunion will be wonderful.</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
